script:
frappe.ui.form.on('Competitor', {
    refresh(frm) {
        if (frm.doc.custom_linkedin_url && !frm.is_new()) {
            frm.add_custom_button(__('Scrape LinkedIn Posts Now'), async () => {
                frappe.show_alert({ message: __('Scraping LinkedIn - this can take up to a minute...'), indicator: 'blue' });
                try {
                    const r = await frappe.call({
                        method: 'competitor_tracking.linkedin_posts_scraper.scrape_competitor_linkedin_posts',
                        args: { competitor_name: frm.doc.name },
                        freeze: true,
                        freeze_message: __('Scraping LinkedIn posts...')
                    });

                    const result = r && r.message;
                    if (!result) {
                        frappe.msgprint({ title: __('Error'), indicator: 'red', message: __('No response received.') });
                        return;
                    }

                    if (!result.success) {
                        frappe.msgprint({ title: __('Scrape Failed'), indicator: 'red', message: __(result.error || 'Unknown error') });
                        return;
                    }

                    if (result.new_posts > 0) {
                        frappe.msgprint({
                            title: __('Scrape Complete'),
                            indicator: 'green',
                            message: __('Found {0} new post(s). <a href="/app/competitor-log/{1}">View Competitor Log</a>', [result.new_posts, result.log])
                        });
                    } else {
                        frappe.msgprint({
                            title: __('Scrape Complete'),
                            indicator: 'blue',
                            message: __(result.message || 'No new posts found.')
                        });
                    }
                } catch (err) {
                    frappe.msgprint({ title: __('Error'), indicator: 'red', message: __(err?.message || 'Failed to scrape LinkedIn posts.') });
                }
            });
        }
    }
});
